"""OGE chemistry task 12 bank imported from the user-provided PDF.

The source contains 99 matching tasks and the official answer table on page 27.
Text is stored compressed only to keep this module compact.
"""
import base64
import json
import zlib

_DATA = """"""

def _load():
    raw = zlib.decompress(base64.b64decode(_DATA.encode("ascii"))).decode("utf-8")
    return json.loads(raw)

OGE12_BANK = _load()

def validate_oge12_bank():
    assert len(OGE12_BANK) == 99
    seen=set()
    for task in OGE12_BANK:
        tid=int(task["id"])
        assert 1 <= tid <= 99 and tid not in seen
        seen.add(tid)
        assert len(task["reactants"]) == 3
        assert len(task["options"]) == 4
        answer=str(task["answer"])
        assert len(answer) == 3 and all(ch in "1234" for ch in answer)
        assert 1 <= int(task["source_page"]) <= 26
    return {"tasks":len(OGE12_BANK),"first":min(seen),"last":max(seen)}
